    // ============================================================
    // MINECRAFT DETECTION
    // ============================================================
    static bool IsMinecraftFocused()
    {
        try
        {
            IntPtr hWnd = GetForegroundWindow();
            if (hWnd == IntPtr.Zero) return false;

            // Metodo 1: per process name
            uint processId;
            GetWindowThreadProcessId(hWnd, out processId);
            if (processId != 0)
            {
                Process process = Process.GetProcessById((int)processId);
                string name = process.ProcessName.ToLower();
                if (name == "javaw" || name == "java" || name == "minecraft" || name == "minecraftlauncher" || name == "minecraft.windows")
                    return true;
            }

            // Metodo 2: per window title (fallback per versioni moderne)
            var sb = new System.Text.StringBuilder(256);
            GetWindowText(hWnd, sb, 256);
            string title = sb.ToString().ToLower();
            if (title.Contains("minecraft") || title.Contains("mc "))
                return true;

            return false;
        }
        catch
        {
            return false;
        }
    }

    // ============================================================
    // INPUT MODERNO CON SendInput
    // ============================================================
    static void SendKey(ushort scanCode, bool keyUp)
    {
        INPUT[] inputs = new INPUT[1];
        inputs[0] = new INPUT();
        inputs[0].type = INPUT_KEYBOARD;
        inputs[0].u.ki = new KEYBDINPUT();
        inputs[0].u.ki.wVk = 0;
        inputs[0].u.ki.wScan = scanCode;
        inputs[0].u.ki.dwFlags = KEYEVENTF_SCANCODE | (keyUp ? KEYEVENTF_KEYUP : 0);
        inputs[0].u.ki.time = 0;
        inputs[0].u.ki.dwExtraInfo = IntPtr.Zero;
        SendInput(1, inputs, Marshal.SizeOf(typeof(INPUT)));
    }

    static void PressKeyScan(ushort scanCode)
    {
        SendKey(scanCode, false);  // KeyDown
        SendKey(scanCode, true);   // KeyUp
    }

    static void SendMouse(uint flags)
    {
        INPUT[] inputs = new INPUT[1];
        inputs[0] = new INPUT();
        inputs[0].type = INPUT_MOUSE;
        inputs[0].u.mi = new MOUSEINPUT();
        inputs[0].u.mi.dx = 0;
        inputs[0].u.mi.dy = 0;
        inputs[0].u.mi.mouseData = 0;
        inputs[0].u.mi.dwFlags = flags;
        inputs[0].u.mi.time = 0;
        inputs[0].u.mi.dwExtraInfo = IntPtr.Zero;
        SendInput(1, inputs, Marshal.SizeOf(typeof(INPUT)));
    }

    static void ClickRight()
    {
        SendMouse(MOUSEEVENTF_RIGHTDOWN);
        Thread.Sleep(1);
        SendMouse(MOUSEEVENTF_RIGHTUP);
    }

    static void ClickLeft()
    {
        SendMouse(MOUSEEVENTF_LEFTDOWN);
        Thread.Sleep(1);
        SendMouse(MOUSEEVENTF_LEFTUP);
    }

    static void ClickLeftHold()
    {
        SendMouse(MOUSEEVENTF_LEFTDOWN);
    }

    static void ClickLeftRelease()
    {
        SendMouse(MOUSEEVENTF_LEFTUP);
    }

    static bool IsKeyPressed(int vkCode)
    {
        return (GetAsyncKeyState(vkCode) & 0x8000) != 0;
    }

    static ushort GetScanCode(string key)
    {
        key = key.ToLower().Trim();
        if (scanMap.ContainsKey(key))
            return scanMap[key];
        return 0;
    }

    static int GetVKCode(string key)
    {
        key = key.ToLower().Trim();
        if (vkMap.ContainsKey(key))
            return vkMap[key];
        return 0;
    }

    // ============================================================
    // AUTO TOTEM MIGLIORATO
    // ============================================================
    static void RunAutoTotem()
    {
        // Scan code per E (apri inventario)
        ushort eScan = 0x12;
        ushort fScan = 0x21;
        ushort escScan = 0x01;

        // Scan code per slot 1-9
        ushort[] slotScans = { 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A };

        while (autoTotemActive)
        {
            if (!IsMinecraftFocused())
            {
                Thread.Sleep(50);
                continue;
            }

            // Se premi il tasto G (o configurato), esegui un refill manuale / auto
            if (IsKeyPressed(autoTotemKeybindCode))
            {
                // === FASE 1: Apri inventario ===
                PressKeyScan(eScan);    // E
                Thread.Sleep(80 + autoTotemDelay);

                // === FASE 2: Trova un totem nell'hotbar (slot 1-9) ===
                // Prima controlla se lo slot 1 ha già un totem — se sì, F per spostare
                // Poi scorre slot 2-9 per trovare altri totem

                bool totemMoved = false;

                for (int slotIdx = 0; slotIdx < 9 && autoTotemActive; slotIdx++)
                {
                    if (!IsKeyPressed(autoTotemKeybindCode) && slotIdx > 0)
                        break;

                    // Seleziona slot
                    PressKeyScan(slotScans[slotIdx]);
                    Thread.Sleep(30 + autoTotemDelay/2);

                    // Premi F per spostare in offhand
                    PressKeyScan(fScan);
                    Thread.Sleep(40 + autoTotemDelay/2);

                    // Se è il primo slot, consideriamo spostato
                    if (slotIdx == 0)
                    {
                        totemMoved = true;
                    }
                }

                // === FASE 3: Se non abbiamo spostato nulla col primo ciclo, 
                // prova a cercare nell'inventario (slot inventory veri) ===
                if (!totemMoved && autoTotemActive)
                {
                    // Shift+click per spostare velocemente (se ci sono totem nell'inventario)
                    // Shift = scan 0x2A
                    SendKey(0x2A, false); // Shift Down
                    Thread.Sleep(10);

                    for (int slotIdx = 0; slotIdx < 9 && autoTotemActive; slotIdx++)
                    {
                        if (!IsKeyPressed(autoTotemKeybindCode) && slotIdx > 0)
                            break;

                        PressKeyScan(slotScans[slotIdx]);
                        Thread.Sleep(20);
                    }

                    SendKey(0x2A, true); // Shift Up
                    Thread.Sleep(30);
                }

                // === FASE 4: Chiudi inventario ===
                PressKeyScan(eScan);    // E
                Thread.Sleep(40);

                // === FASE 5: Aspetta che il tasto venga rilasciato ===
                while (IsKeyPressed(autoTotemKeybindCode) && autoTotemActive)
                {
                    Thread.Sleep(10);
                }
            }

            Thread.Sleep(5);
        }
    }

    // ============================================================
    // RUNNER MIGLIORATI CON TIMING PRECISI
    // ============================================================

    static void RunAirplace(ModuleConfig config)
    {
        bool lastState = false;

        while (activeModules.ContainsKey("airplace") && activeModules["airplace"])
        {
            bool currentState = IsKeyPressed(config.KeybindCode);

            if (currentState && !lastState && IsMinecraftFocused())
            {
                // Sequenza airplace: posiziona 3 blocchi in loop
                // Delay ottimizzati per 20 tick/s (50ms per tick)
                for (int cycle = 0; cycle < 2 && activeModules.ContainsKey("airplace") && activeModules["airplace"]; cycle++)
                {
                    if (!IsKeyPressed(config.KeybindCode))
                    {
                        // Se rilasci il tasto, esci solo se siamo nel secondo ciclo
                        if (cycle == 1) break;
                    }

                    PressKeyScan(config.Slot1Scan);
                    Thread.Sleep(5);
                    ClickRight();
                    Thread.Sleep(config.DelayMs1 > 0 ? config.DelayMs1 : 65);

                    PressKeyScan(config.Slot2Scan);
                    Thread.Sleep(5);
                    ClickRight();
                    Thread.Sleep(config.DelayMs2 > 0 ? config.DelayMs2 : 70);

                    PressKeyScan(config.Slot3Scan);
                    Thread.Sleep(5);
                    ClickRight();
                    Thread.Sleep(config.DelayMs3 > 0 ? config.DelayMs3 : 50);
                }
            }

            lastState = currentState;
            Thread.Sleep(5); // Riduce CPU usage
        }
    }

    static void RunSingle(ModuleConfig config)
    {
        bool lastState = false;

        while (activeModules.ContainsKey("single") && activeModules["single"])
        {
            bool currentState = IsKeyPressed(config.KeybindCode);

            if (currentState && !lastState && IsMinecraftFocused())
            {
                int baseDelay = config.Delay > 0 ? config.Delay : 50;

                PressKeyScan(config.Slot1Scan);
                Thread.Sleep(5);
                ClickRight();
                Thread.Sleep(config.DelayMs1 > 0 ? config.DelayMs1 : baseDelay);

                PressKeyScan(config.Slot2Scan);
                Thread.Sleep(5);
                ClickRight();
                Thread.Sleep(config.DelayMs2 > 0 ? config.DelayMs2 : baseDelay);

                PressKeyScan(config.Slot3Scan);
                Thread.Sleep(5);
                ClickRight();
                Thread.Sleep(config.DelayMs3 > 0 ? config.DelayMs3 : baseDelay);
            }

            lastState = currentState;
            Thread.Sleep(5);
        }
    }

    static void RunDouble(ModuleConfig config)
    {
        bool lastState = false;

        while (activeModules.ContainsKey("double") && activeModules["double"])
        {
            bool currentState = IsKeyPressed(config.KeybindCode);

            if (currentState && !lastState && IsMinecraftFocused())
            {
                int baseDelay = config.Delay > 0 ? config.Delay : 50;

                // Cycle 1
                PressKeyScan(config.Slot1Scan);
                Thread.Sleep(5);
                ClickRight();
                Thread.Sleep(config.DelayMs1 > 0 ? config.DelayMs1 : baseDelay);

                PressKeyScan(config.Slot2Scan);
                Thread.Sleep(5);
                ClickRight();
                Thread.Sleep(config.DelayMs2 > 0 ? config.DelayMs2 : baseDelay);

                PressKeyScan(config.Slot3Scan);
                Thread.Sleep(5);
                ClickRight();
                Thread.Sleep(config.DelayMs3 > 0 ? config.DelayMs3 : baseDelay);

                // Cycle 2
                PressKeyScan(config.Slot1Scan);
                Thread.Sleep(5);
                ClickRight();
                Thread.Sleep(config.DelayMs4 > 0 ? config.DelayMs4 : baseDelay);

                PressKeyScan(config.Slot2Scan);
                Thread.Sleep(5);
                ClickRight();
                Thread.Sleep(config.DelayMs5 > 0 ? config.DelayMs5 : baseDelay);

                PressKeyScan(config.Slot3Scan);
                Thread.Sleep(5);
                ClickRight();
                Thread.Sleep(config.DelayMs6 > 0 ? config.DelayMs6 : baseDelay);
            }

            lastState = currentState;
            Thread.Sleep(5);
        }
    }

    static void RunHitCrystal(ModuleConfig config)
    {
        bool lastState = false;
        bool isExecuting = false;

        while (activeModules.ContainsKey("hitcrystal") && activeModules["hitcrystal"])
        {
            bool currentState = IsKeyPressed(config.KeybindCode);

            if (!currentState && lastState)
            {
                isExecuting = false;
                // Rilascia left click se tenuto premuto
                ClickLeftRelease();
            }

            if (currentState && !lastState && !isExecuting && IsMinecraftFocused())
            {
                isExecuting = true;

                // 1. Seleziona slot obsidian e piazza
                PressKeyScan(config.Slot2Scan);
                Thread.Sleep(5);
                ClickRight();
                Thread.Sleep(config.DelayMs1 > 0 ? config.DelayMs1 : 45);

                // 2. Switch a crystal
                PressKeyScan(config.Slot1Scan);
                Thread.Sleep(config.DelayMs2 > 0 ? config.DelayMs2 : 10);

                // 3. Loop crystal break (tieni premuto keybind)
                int crystalClicks = 0;
                while (IsKeyPressed(config.KeybindCode) && 
                       activeModules.ContainsKey("hitcrystal") && 
                       activeModules["hitcrystal"] && 
                       IsMinecraftFocused() &&
                       crystalClicks < 30) // Safety limit
                {
                    ClickRight();
                    Thread.Sleep(config.DelayMs3 > 0 ? config.DelayMs3 : 18);
                    ClickLeft();
                    Thread.Sleep(config.DelayMs4 > 0 ? config.DelayMs4 : 18);
                    crystalClicks++;
                }

                isExecuting = false;
            }

            lastState = currentState;
            Thread.Sleep(5);
        }
    }

