            if (activeModules.ContainsKey("single") && activeModules["single"])
                singlePanel.BorderStyle = BorderStyle.FixedSingle;
            else
                singlePanel.BorderStyle = BorderStyle.None;

            if (activeModules.ContainsKey("double") && activeModules["double"])
                doublePanel.BorderStyle = BorderStyle.FixedSingle;
            else
                doublePanel.BorderStyle = BorderStyle.None;

            if (activeModules.ContainsKey("hitcrystal") && activeModules["hitcrystal"])
                hitcrystalPanel.BorderStyle = BorderStyle.FixedSingle;
            else
                hitcrystalPanel.BorderStyle = BorderStyle.None;
        }

