            var configBtn = new Button();
            configBtn.Text = "CONFIG";
            configBtn.Location = new Point(40, 175);
            configBtn.Size = new Size(80, 28);
            configBtn.Font = new Font("Segoe UI", 9, FontStyle.Bold);
            configBtn.BackColor = Color.White;
            configBtn.ForeColor = Color.Black;
            configBtn.FlatStyle = FlatStyle.Flat;
            configBtn.Cursor = Cursors.Hand;
            configBtn.FlatAppearance.BorderSize = 0;

            configBtn.Click += delegate { OpenTotemConfig(panel); };

            panel.Controls.Add(nameLabel);
            panel.Controls.Add(keybindLabel);
            panel.Controls.Add(statusDot);
            panel.Controls.Add(statusText);
            panel.Controls.Add(infoLabel);
            panel.Controls.Add(configBtn);

            panel.Click += delegate
            {
                if (!panel.Controls.OfType<Button>().Any(b => b.ClientRectangle.Contains(panel.PointToClient(Cursor.Position))))
                {
                    ToggleTotem(panel);
                }
            };

            return panel;
        }

        private void OpenTotemConfig(Panel panel)
        {
            var configForm = new Form();
            configForm.Text = "Configure Auto Totem";
            configForm.Size = new Size(400, 300);
            configForm.StartPosition = FormStartPosition.CenterParent;
            configForm.FormBorderStyle = FormBorderStyle.FixedDialog;
            configForm.MaximizeBox = false;
            configForm.MinimizeBox = false;
            configForm.BackColor = Color.FromArgb(30, 30, 30);

            var yPos = 20;

            var keybindLabel = new Label();
            keybindLabel.Text = "Keybind (single key only):";
            keybindLabel.Location = new Point(20, yPos);
            keybindLabel.AutoSize = true;
            keybindLabel.ForeColor = Color.White;
            configForm.Controls.Add(keybindLabel);

            var keybindText = new TextBox();
            keybindText.Location = new Point(20, yPos + 25);
            keybindText.Size = new Size(350, 25);
            keybindText.BackColor = Color.FromArgb(50, 50, 50);
            keybindText.ForeColor = Color.White;
            keybindText.BorderStyle = BorderStyle.FixedSingle;
            keybindText.Text = GetKeyName(autoTotemKeybindCode);
            configForm.Controls.Add(keybindText);

            yPos += 60;

            var delayLabel = new Label();
            delayLabel.Text = "Delay (ms) between slot checks:";
            delayLabel.Location = new Point(20, yPos);
            delayLabel.AutoSize = true;
            delayLabel.ForeColor = Color.White;
            configForm.Controls.Add(delayLabel);

            var delayText = new TextBox();
            delayText.Location = new Point(20, yPos + 25);
            delayText.Size = new Size(350, 25);
            delayText.Text = autoTotemDelay.ToString();
            delayText.BackColor = Color.FromArgb(50, 50, 50);
            delayText.ForeColor = Color.White;
            delayText.BorderStyle = BorderStyle.FixedSingle;
            configForm.Controls.Add(delayText);

            yPos += 60;

            var infoLabel = new Label();
            infoLabel.Text = "Tenendo premuto il tasto:\n1. Apre inventario (E)\n2. Scorre slot 1-9 premendo F per spostare in offhand\n3. Shift+click per inventory slots\n4. Chiude inventario";
            infoLabel.Location = new Point(20, yPos);
            infoLabel.Size = new Size(350, 80);
            infoLabel.ForeColor = Color.FromArgb(150, 150, 150);
            infoLabel.Font = new Font("Segoe UI", 9);
            configForm.Controls.Add(infoLabel);

            yPos += 90;

            var saveBtn = new Button();
            saveBtn.Text = "SAVE";
            saveBtn.Location = new Point(125, yPos);
            saveBtn.Size = new Size(150, 35);
            saveBtn.BackColor = Color.White;
            saveBtn.ForeColor = Color.Black;
            saveBtn.FlatStyle = FlatStyle.Flat;
            saveBtn.Font = new Font("Segoe UI", 10, FontStyle.Bold);
            saveBtn.FlatAppearance.BorderSize = 0;

            saveBtn.Click += delegate
            {
                string key = keybindText.Text.Trim().ToLower();
                int code = GetVKCode(key);

                if (code == 0)
                {
                    MessageBox.Show("Invalid keybind! Please use a single key.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    return;
                }

                if (!int.TryParse(delayText.Text, out int delay) || delay < 10 || delay > 1000)
                {
                    MessageBox.Show("Delay must be between 10 and 1000 ms.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    return;
                }

                autoTotemKeybindCode = code;
                autoTotemDelay = delay;

                foreach (Control ctrl in panel.Controls)
                {
                    if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "keybind")
                    {
                        ((Label)ctrl).Text = "Keybind: " + key.ToUpper();
                    }
                }

                MessageBox.Show("Configuration saved!", "Success", MessageBoxButtons.OK, MessageBoxIcon.Information);
                configForm.Close();
            };

            configForm.Controls.Add(saveBtn);
            configForm.ShowDialog();
        }

        private void ToggleTotem(Panel panel)
        {
            autoTotemActive = !autoTotemActive;

            if (autoTotemActive)
            {
                panel.BackColor = activeColor;
                UpdatePanelColors(panel, Color.White, "Active", Color.White, Color.FromArgb(200, 200, 200), Color.White);

                var thread = new Thread(RunAutoTotem);
                thread.IsBackground = true;
                thread.Start();
            }
            else
            {
                panel.BackColor = cardColor;
                UpdatePanelColors(panel, Color.FromArgb(60, 60, 60), "Inactive", Color.FromArgb(150, 150, 150), Color.FromArgb(130, 130, 130), Color.FromArgb(150, 150, 150));
            }
        }

        private void UpdatePanelColors(Panel panel, Color dotColor, string statusTextVal, Color statusColor, Color infoColor, Color keybindColor)
        {
            foreach (Control ctrl in panel.Controls)
            {
                if (ctrl is Label lbl && lbl.Tag != null)
                {
                    switch (lbl.Tag.ToString())
                    {
                        case "statusdot":
                            lbl.BackColor = dotColor;
                            break;
                        case "statustext":
                            lbl.Text = statusTextVal;
                            lbl.ForeColor = statusColor;
                            break;
                        case "info":
                            lbl.ForeColor = infoColor;
                            break;
                        case "keybind":
                            lbl.ForeColor = keybindColor;
                            break;
                    }
                }
                else if (ctrl is Label lbl2 && lbl2.Tag == null)
                {
                    lbl2.ForeColor = Color.White;
                }
            }
        }

        // ============================================================
        // MODULE CARD
        // ============================================================
        private Panel CreateModuleCard(string name, int x, int y, string moduleId)
        {
            var panel = new Panel();
            panel.Location = new Point(x, y);
            panel.Size = new Size(160, 220);
            panel.BackColor = cardColor;
            panel.BorderStyle = BorderStyle.None;
            panel.Cursor = Cursors.Hand;
            panel.Tag = moduleId;

            var nameLabel = new Label();
            nameLabel.Text = name;
            nameLabel.Font = new Font("Segoe UI", 11, FontStyle.Bold);
            nameLabel.ForeColor = Color.White;
            nameLabel.AutoSize = false;
            nameLabel.Size = new Size(140, 60);
            nameLabel.Location = new Point(10, 20);
            nameLabel.TextAlign = ContentAlignment.TopCenter;

            var statusDot = new Label();
            statusDot.Size = new Size(15, 15);
            statusDot.BackColor = Color.FromArgb(60, 60, 60);
            statusDot.Location = new Point(25, 100);
            statusDot.Tag = "statusdot";

            var statusText = new Label();
            statusText.Text = "Inactive";
            statusText.Font = new Font("Segoe UI", 9);
            statusText.ForeColor = Color.FromArgb(150, 150, 150);
            statusText.AutoSize = true;
            statusText.Location = new Point(45, 98);
            statusText.Tag = "statustext";

            // Info label — mostra la configurazione corrente
            var infoLabel = new Label();
            infoLabel.Text = "Click to activate";
            infoLabel.Font = new Font("Segoe UI", 8);
            infoLabel.ForeColor = Color.FromArgb(130, 130, 130);
            infoLabel.AutoSize = true;
            infoLabel.Location = new Point(35, 120);
            infoLabel.Tag = "info";

            var configBtn = new Button();
            configBtn.Text = "CONFIG";
            configBtn.Location = new Point(40, 165);
            configBtn.Size = new Size(80, 32);
            configBtn.Font = new Font("Segoe UI", 9, FontStyle.Bold);
            configBtn.BackColor = Color.White;
            configBtn.ForeColor = Color.Black;
            configBtn.FlatStyle = FlatStyle.Flat;
            configBtn.Cursor = Cursors.Hand;
            configBtn.FlatAppearance.BorderSize = 0;

            string capturedModuleId = moduleId;
            string capturedName = name;
            Panel capturedPanel = panel;

            configBtn.Click += delegate { OpenConfig(capturedModuleId, capturedName, capturedPanel); };

            panel.Controls.Add(nameLabel);
            panel.Controls.Add(statusDot);
            panel.Controls.Add(statusText);
            panel.Controls.Add(infoLabel);
            panel.Controls.Add(configBtn);

            panel.Click += delegate
            {
                if (!panel.Controls.OfType<Button>().Any(b => b.ClientRectangle.Contains(panel.PointToClient(Cursor.Position))))
                {
                    ToggleModule(capturedModuleId, capturedPanel);
                }
            };

            return panel;
        }

        // ============================================================
        // CONFIG WINDOW
        // ============================================================
        private void OpenConfig(string moduleId, string moduleName, Panel panel)
        {
            var configForm = new Form();
            configForm.Text = "Configure " + moduleName;
            configForm.Size = new Size(450, 550);
            configForm.StartPosition = FormStartPosition.CenterParent;
            configForm.FormBorderStyle = FormBorderStyle.FixedDialog;
            configForm.MaximizeBox = false;
            configForm.MinimizeBox = false;
            configForm.BackColor = Color.FromArgb(30, 30, 30);

            var mainPanel = new Panel();
            mainPanel.Location = new Point(0, 0);
            mainPanel.Size = new Size(450, 500);
            mainPanel.AutoScroll = true;
            mainPanel.BackColor = Color.FromArgb(30, 30, 30);
            configForm.Controls.Add(mainPanel);

            var yPos = 20;

            // ====== KEYBIND ======
            AddLabel(mainPanel, "Keybind (single key only):", ref yPos);
            var keybindText = AddTextBox(mainPanel, ref yPos);
            if (moduleConfigs.ContainsKey(moduleId))
                keybindText.Text = moduleConfigs[moduleId].Keybind;

            yPos += 10;

            // ====== SLOTS ======
            string slot1Label, slot2Label, slot3Label;

            if (moduleId == "hitcrystal")
            {
                slot1Label = "Crystal Slot (1-9):";
                slot2Label = "Obsidian Slot (1-9):";
                slot3Label = null;
            }
            else
            {
                slot1Label = "Anchor Slot (1-9):";
                slot2Label = "Glowstone Slot (1-9):";
                slot3Label = "Totem/Switch Slot (1-9):";
            }

            AddLabel(mainPanel, slot1Label, ref yPos);
            var slot1Text = AddTextBox(mainPanel, ref yPos);

            AddLabel(mainPanel, slot2Label, ref yPos);
            var slot2Text = AddTextBox(mainPanel, ref yPos);

            TextBox slot3Text = null;
            if (slot3Label != null)
            {
                AddLabel(mainPanel, slot3Label, ref yPos);
                slot3Text = AddTextBox(mainPanel, ref yPos);
            }

            yPos += 5;

            // ====== DELAY ======
            if (moduleId != "airplace" && moduleId != "hitcrystal")
            {
                AddLabel(mainPanel, "Default Delay (ms) — usato se delay specifici sono 0:", ref yPos);
                var delayText = AddTextBox(mainPanel, ref yPos, "50");
                if (moduleConfigs.ContainsKey(moduleId))
                    delayText.Text = moduleConfigs[moduleId].Delay.ToString();
                delayText.Tag = "delay_default";
                yPos += 5;
            }

            // ====== PER-STEP DELAYS ======
            yPos += 5;
            var stepLabel = new Label();
            stepLabel.Text = "--- Per-step delays (0 = usa default) ---";
            stepLabel.Location = new Point(20, yPos);
            stepLabel.AutoSize = true;
            stepLabel.ForeColor = Color.FromArgb(200, 200, 100);
            stepLabel.Font = new Font("Segoe UI", 9, FontStyle.Bold);
            mainPanel.Controls.Add(stepLabel);
            yPos += 25;

            string[] delayNames;
            if (moduleId == "hitcrystal")
                delayNames = new[] {"Delay place obsidian", "Delay switch crystal", "Delay right click", "Delay left click"};
            else if (moduleId == "airplace")
                delayNames = new[] {"Delay step 1", "Delay step 2", "Delay step 3", "Delay step 4", "Delay step 5", "Delay step 6"};
            else
                delayNames = new[] {"Delay step 1", "Delay step 2", "Delay step 3", "Delay step 4", "Delay step 5", "Delay step 6"};

            var delayBoxes = new TextBox[6];
            for (int i = 0; i < delayNames.Length; i++)
            {
                AddLabel(mainPanel, delayNames[i] + " (ms):", ref yPos);
                delayBoxes[i] = AddTextBox(mainPanel, ref yPos);
                yPos += 2;
            }

            // Pre-carica se già configurato
            if (moduleConfigs.ContainsKey(moduleId))
            {
                var config = moduleConfigs[moduleId];
                slot1Text.Text = config.Slot1Name ?? GetKeyName(config.Slot1Scan);
                slot2Text.Text = config.Slot2Name ?? GetKeyName(config.Slot2Scan);
                if (slot3Text != null) slot3Text.Text = config.Slot3Name ?? GetKeyName(config.Slot3Scan);

                int[] delays = { config.DelayMs1, config.DelayMs2, config.DelayMs3, config.DelayMs4, config.DelayMs5, config.DelayMs6 };
                for (int i = 0; i < delayNames.Length && i < 6; i++)
                {
                    if (delays[i] > 0)
                        delayBoxes[i].Text = delays[i].ToString();
                }
            }

            yPos += 15;

            // ====== SAVE BUTTON ======
            var saveBtn = new Button();
            saveBtn.Text = "SAVE CONFIG";
            saveBtn.Location = new Point(125, yPos);
            saveBtn.Size = new Size(180, 40);
            saveBtn.BackColor = Color.White;
            saveBtn.ForeColor = Color.Black;
            saveBtn.FlatStyle = FlatStyle.Flat;
            saveBtn.Font = new Font("Segoe UI", 11, FontStyle.Bold);
            saveBtn.FlatAppearance.BorderSize = 0;

            string capturedId = moduleId;
            Panel capturedPanel = panel;

            saveBtn.Click += delegate
            {
                try
                {
                    var config = new ModuleConfig();
                    config.Keybind = keybindText.Text.Trim().ToLower();
                    config.KeybindCode = GetVKCode(config.Keybind);

                    if (config.KeybindCode == 0)
                    {
                        MessageBox.Show("Invalid keybind! Use a single key (1-9, a-z, etc).", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                        return;
                    }

                    config.Slot1Name = slot1Text.Text.Trim().ToLower();
                    config.Slot1Scan = GetScanCode(config.Slot1Name);
                    config.Slot2Name = slot2Text.Text.Trim().ToLower();
                    config.Slot2Scan = GetScanCode(config.Slot2Name);

                    if (slot3Text != null)
                    {
                        config.Slot3Name = slot3Text.Text.Trim().ToLower();
                        config.Slot3Scan = GetScanCode(config.Slot3Name);
                    }

                    // Default delay
                    var defaultDelayCtrl = mainPanel.Controls.OfType<TextBox>().FirstOrDefault(t => t.Tag != null && t.Tag.ToString() == "delay_default");
                    if (defaultDelayCtrl != null)
                        config.Delay = int.Parse(defaultDelayCtrl.Text);
                    else
                        config.Delay = 50;

                    config.DelayMs1 = ParseDelay(delayBoxes[0]);
                    config.DelayMs2 = ParseDelay(delayBoxes[1]);
                    config.DelayMs3 = ParseDelay(delayBoxes[2]);
                    config.DelayMs4 = delayBoxes[3] != null ? ParseDelay(delayBoxes[3]) : 0;
                    config.DelayMs5 = delayBoxes[4] != null ? ParseDelay(delayBoxes[4]) : 0;
                    config.DelayMs6 = delayBoxes[5] != null ? ParseDelay(delayBoxes[5]) : 0;

                    moduleConfigs[capturedId] = config;

                    // Aggiorna info label
                    foreach (Control ctrl in capturedPanel.Controls)
                    {
                        if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "info")
                        {
                            ((Label)ctrl).Text = config.Keybind.ToUpper() + " | Slots: " + 
                                config.Slot1Name.ToUpper() + "," + config.Slot2Name.ToUpper() +
                                (config.Slot3Name != null ? "," + config.Slot3Name.ToUpper() : "");
                        }
                    }

                    MessageBox.Show("Configuration saved!", "Success", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    configForm.Close();
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Error: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            };

            mainPanel.Controls.Add(saveBtn);
            configForm.ShowDialog();
        }

        private int ParseDelay(TextBox tb)
        {
            if (tb == null || string.IsNullOrWhiteSpace(tb.Text)) return 0;
            if (int.TryParse(tb.Text, out int val)) return Math.Max(0, val);
            return 0;
        }

        private void AddLabel(Control parent, string text, ref int y)
        {
            var lbl = new Label();
            lbl.Text = text;
            lbl.Location = new Point(20, y);
            lbl.AutoSize = true;
            lbl.ForeColor = Color.White;
            lbl.Font = new Font("Segoe UI", 9);
            parent.Controls.Add(lbl);
            y += 22;
        }

        private TextBox AddTextBox(Control parent, ref int y, string defaultValue = "")
        {
            var tb = new TextBox();
            tb.Location = new Point(20, y);
            tb.Size = new Size(390, 25);
            tb.Text = defaultValue;
            tb.BackColor = Color.FromArgb(50, 50, 50);
            tb.ForeColor = Color.White;
            tb.BorderStyle = BorderStyle.FixedSingle;
            tb.Font = new Font("Segoe UI", 9);
            parent.Controls.Add(tb);
            y += 30;
            return tb;
        }

        private string GetKeyName(int vkCode)
        {
            foreach (var pair in vkMap)
            {
                if (pair.Value == vkCode)
                    return pair.Key;
            }
            return "";
        }

        private string GetKeyName(ushort scanCode)
        {
            foreach (var pair in scanMap)
            {
                if (pair.Value == scanCode)
                    return pair.Key;
            }
            return "";
        }

        // ============================================================
        // TOGGLE MODULE
        // ============================================================
        private void ToggleModule(string moduleId, Panel panel)
        {
            if (!moduleConfigs.ContainsKey(moduleId))
            {
                MessageBox.Show("Configure the module first by clicking CONFIG!", "Warning", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            lock (moduleLock)
            {
                if (activeModules.ContainsKey(moduleId) && activeModules[moduleId])
                {
                    // SPEGNI
                    activeModules[moduleId] = false;
                    panel.BackColor = cardColor;

                    foreach (Control ctrl in panel.Controls)
                    {
                        if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "statusdot")
                            ctrl.BackColor = Color.FromArgb(60, 60, 60);
                        if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "statustext")
                        {
                            ((Label)ctrl).Text = "Inactive";
                            ctrl.ForeColor = Color.FromArgb(150, 150, 150);
                        }
                        if (ctrl is Label && ctrl.Tag == null)
                            ctrl.ForeColor = Color.White;
                    }

                    panel.BorderStyle = BorderStyle.None;
                }
                else
                {
                    // ACCENDI
                    if (!activeModules.ContainsKey(moduleId))
                        activeModules.Add(moduleId, true);
                    else
                        activeModules[moduleId] = true;

                    panel.BackColor = activeColor;

                    foreach (Control ctrl in panel.Controls)
                    {
                        if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "statusdot")
                            ctrl.BackColor = Color.White;
                        if (ctrl is Label && ctrl.Tag != null && ctrl.Tag.ToString() == "statustext")
                        {
                            ((Label)ctrl).Text = "Active";
                            ctrl.ForeColor = Color.White;
                        }
                        if (ctrl is Label && ctrl.Tag == null)
                            ctrl.ForeColor = Color.White;
                    }

                    panel.BorderStyle = BorderStyle.FixedSingle;

                    // Avvia thread
                    var config = moduleConfigs[moduleId];
                    string capturedId = moduleId;

                    var thread = new Thread(() =>
                    {
                        try
                        {
                            switch (capturedId)
                            {
                                case "airplace": RunAirplace(config); break;
                                case "single": RunSingle(config); break;
                                case "double": RunDouble(config); break;
                                case "hitcrystal": RunHitCrystal(config); break;
                            }
                        }
                        catch (Exception ex)
                        {
                            Debug.WriteLine("Module thread error: " + ex.Message);
                        }
                        finally
                        {
                            lock (moduleLock)
                            {
                                if (activeModules.ContainsKey(capturedId))
                                    activeModules[capturedId] = false;
                            }
                        }
                    });

                    thread.IsBackground = true;
                    thread.Start();

                    if (moduleThreads.ContainsKey(moduleId))
                        moduleThreads[moduleId] = thread;
                    else
                        moduleThreads.Add(moduleId, thread);
                }
            }
        }
    }
}
